cat > /tmp/neutrino-fast-live-b4eG5i/multi_source_retrieval/fast_dag/1/sum.js <<'EOF'
const fs = require('fs');
const files = ['a.txt', 'b.txt', 'c.txt'];
const rows = files.map((f) => {
  const raw = fs.readFileSync(f, 'utf8');
  const m = raw.trim().match(/^([A-Za-z]+) population:\s*(\d+)$/);
  if (!m) throw new Error(`unexpected format in ${f}: ${JSON.stringify(raw)}`);
  const value = Number(m[2]);
  if (!Number.isSafeInteger(value)) throw new Error(`non-integer population in ${f}`);
  return { file: f, label: m[1], value };
});
// cross-check: each population appears exactly once, labels distinct
const labels = rows.map((r) => r.label);
if (new Set(labels).size !== labels.length) throw new Error('duplicate population labels');
for (const r of rows) {
  const raw = fs.readFileSync(r.file, 'utf8');
  if (!raw.includes(String(r.value))) throw new Error(`re-read mismatch for ${r.file}`);
}
const total = rows.reduce((s, r) => s + r.value, 0);
const answer = { total };
fs.writeFileSync('answer.json', JSON.stringify(answer) + '\n');
console.log(JSON.stringify({ rows, total }, null, 2));
EOF
